/**
 * Fixed follow-up items. They are written once, here, and are never generated by
 * a model. They appear only when the scores show an unresolved tie (work interests)
 * or a ceiling (work values). Original wording for this app, unvalidated.
 *
 * Every option in a question is written to be about equally appealing, so the
 * choice reflects preference and not which answer sounds best.
 */

export const NO_CHOICE = 'none'
export const NO_CHOICE_LABEL = 'I cannot choose between these'

export interface InterestScenario {
  id: string
  prompt: string
  /** Option text keyed by the interest area letter. */
  options: Readonly<Record<string, string>>
}

